class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        cost = add = 0
        for i in range(1, len(nums)):
            need = nums[i - 1] + add - nums[i]
            if need > 0:
                cost += need
                add += need
        return cost

c.cpp:
class Solution {
public:
    long long minimumOperations(vector<int>& nums) {
        long long cost = 0, add = 0;
        for (int i = 1; i < (int)nums.size(); ++i) {
            long long need = (long long)nums[i - 1] + add - nums[i];
            if (need > 0) { cost += need; add += need; }
        }
        return cost;
    }
};

